import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.CcJ8wlZS.js";const u=JSON.parse('{"title":"Team Sync — share the corpus","description":"One fabric per machine, one corpus shared via git","frontmatter":{"type":"index","title":"Team Sync — share the corpus","description":"One fabric per machine, one corpus shared via git","created":"2026-09-19T00:00:00.000Z","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"sync.md","filePath":"sync.md"}'),n={name:"sync.md"};function r(o,s,h,p,c,l){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="team-sync-share-the-corpus-as-source-of-truth-share-the-corpus-as-source-of-truth" tabindex="-1">Team Sync: Share the Corpus as Source of Truth: Share the Corpus as Source of Truth <a class="header-anchor" href="#team-sync-share-the-corpus-as-source-of-truth-share-the-corpus-as-source-of-truth" aria-label="Permalink to &quot;Team Sync: Share the Corpus as Source of Truth: Share the Corpus as Source of Truth&quot;">​</a></h1><p>One fabric per machine, <strong>one corpus shared via git</strong>. <code>wf sync</code> pushes/pulls your knowledge content (claims, sources, patterns, skills, concepts, experience events, decisions, syntheses, registry) to a shared git remote — a private GitHub repo works well. The harness (scripts, schemas) stays per-machine and updates via <code>wf update</code> from the public repo; content and code have different lifecycles and remotes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># One-time: point your fabric at the shared corpus remote</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (or pass --corpus &lt;git-url&gt; to the installer and this is done for you)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:your-org/wiki-fabric-corpus.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Day-to-day, on any machine:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # ahead/behind + uncommitted corpus changes + conflicts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ingested upstream docs&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # commit + push corpus changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # fetch + merge; conflicts → review queue</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A teammate joins: clone your fabric, then</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:your-org/wiki-fabric-corpus.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre></div><p><strong>How bootstrap meets the corpus:</strong> when you <code>wf bootstrap</code> a project into a fabric with a corpus remote, the bootstrap writes a small <code>projects/&lt;slug&gt;/README.md</code> (title, owner, date, upstream sources) into the namespace — that README syncs to the corpus, so teammates see <em>what</em> the new project is the moment it lands. Bootstrap prints whether the project is local-only or corpus-wired, and <code>wf sync status</code> lists new namespaces waiting on the remote (&quot;New projects on the corpus (pull to receive)&quot;); <code>wf sync pull</code> announces each namespace it delivers, with owner. Teammates discover new projects by pulling — nothing to configure on their side.</p><p><strong>Conflict policy — review queue, never silent overwrite:</strong> if two machines changed the same file, <code>wf sync pull</code> aborts the merge and writes a conflict dossier to <code>registry/conflicts/&lt;date&gt;/</code> containing <em>both</em> versions (ours vs theirs) side by side. The fabric stays clean; you decide. Unresolved conflicts make <code>wf lint</code> fail (SYNC-CONFLICT errors) and block <code>wf sync push</code>, so a disagreement can&#39;t sneak into the shared truth. Resolve by picking the correct version for the source page, delete the conflict file, then push.</p><p><strong>Why a separate remote from this public repo:</strong> this repo is the public harness; your corpus is your private knowledge. Keeping them on different remotes means <code>wf update</code> (harness) never touches team content, and <code>wf sync</code> never publishes your corpus to a public URL.</p><hr>`,7)])])}const k=e(n,[["render",r]]);export{u as __pageData,k as default};
